import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    var ans = 0
    var met = false
    val reader = BufferedReader(InputStreamReader(System.`in`))

    reader.use {
        var line: String?
        while (true) {
            line = it.readLine()
            if (line == null) break

            if (line == "BBBBBBBB") {
                ans++
            } else if (!met) {
                val count = line.count { it == 'B' }
                if (count > 0) {
                    ans += count
                }
                met = true
            }
        }
    }

    println(ans)
}

import java.util.regex.Pattern

fun main() {
    var ans = 0
    var met = false
    val pattern = Pattern.compile("B")

    System.stdin.buffer().reader().readLines().forEach { input ->
        val matcher = pattern.matcher(input)
        var count = 0
        while (matcher.find()) {
            count++
        }

        if (input == "BBBBBBBB") {
            ans++
        } else if (!met) {
            if (count > 0) {
                ans += count
            }
            met = true
        }
    }

    println(ans)
}

import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    var ans = 0
    var met = false

    while (scanner.hasNextLine()) {
        val input = scanner.nextLine()
        val temp = input.count { it == 'B' }

        if (input == "BBBBBBBB") {
            ans++
        } else if (!met) {
            if (temp > 0) {
                ans += temp
            }
            met = true
        }
    }

    println(ans)
}

